__NUXT_JSONP__("/trlp-thanks", {data:[{details:{slug:"en",pageTitle:"Thanks Contact | Mentor Language Institute",pageDescription:"Thank you for your inquiry to Mentor Language Institute.",title:"Thanks Contact",subtitle:["Thank you for your inquiry to Mentor Language Institute.\u003Cbr \u002F\u003EAn admission staff member will respond to you shortly.","The process for studying abroad in the United States is very complicated, we can guide you the procedures over the phone.","If you didn't check \"Do not contact me by phone\", we will call you in a day or two.","Best regards,"],dir:"\u002Ftrlp-thanks",path:"\u002Ftrlp-thanks\u002Fen",extension:".json",createdAt:"2026-10-22T16:31:31.303Z",updatedAt:"2025-05-26T12:06:27.950Z"}}],fetch:{},mutations:void 0});